-- LifeOS Migration 0031: Global Food Library Seed
--
-- Redesign Nutrition spec, Section 4/5/6 — the American food library
-- (proteins/whole grains/vegetables/fruits/nuts & seeds) plus
-- individual Senegalese food items (complementing the already-seeded
-- Senegalese meals from migration 0027 — no existing meal data is
-- touched here) and 10 common American meals. Also seeds 3 example
-- rows (fresh grilled / deep-fried / heavily salted fish) directly
-- demonstrating Section 6's "the same food may have a different
-- classification depending on preparation" rule.
--
-- Nutrition figures are general estimates for the stated serving size
-- (documented the same way as meals.calories_kcal etc. — never
-- presented as lab-measured). Idempotent: only inserts a food/meal
-- whose (name_en, cuisine) or name_en doesn't already exist, same
-- WHERE NOT EXISTS pattern as migration 0027 (never ON CONFLICT — see
-- the migration 0024 42P10 postmortem earlier in this project).

insert into foods (name_en, name_fr, common_names, cuisine, country_region, category, serving_size_en, serving_size_fr, calories_kcal, protein_g, carbs_g, fat_g, fiber_g, sugar_g, added_sugar_g, sodium_mg, saturated_fat_g, preparation_method_en, preparation_method_fr, health_tags, classification, classification_reason_en, classification_reason_fr)
