-- American meals (Section 4's "Common American Meals" list).
insert into meals (name_en, name_fr, description_en, description_fr, cuisine, meal_type, serving_size_en, serving_size_fr, ingredients, preparation_en, preparation_fr, calories_kcal, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, rating, rating_reason_en, rating_reason_fr, tags)
