from (
  values
  ('Oatmeal with Berries and Walnuts', 'Flocons d''avoine aux baies et aux noix', 'A warm bowl of oatmeal topped with fresh berries and walnuts.', 'Un bol de flocons d''avoine chaud garni de baies fraîches et de noix.', 'american', 'breakfast', '1 bowl', '1 bol', jsonb_build_array(jsonb_build_object('en', 'Oatmeal', 'fr', 'Flocons d''avoine'), jsonb_build_object('en', 'Mixed berries', 'fr', 'Baies mélangées'), jsonb_build_object('en', 'Walnuts', 'fr', 'Noix'), jsonb_build_object('en', 'Cinnamon (optional)', 'fr', 'Cannelle (facultatif)')), 'Cook oatmeal with water or milk, top with berries and chopped walnuts.', 'Cuire les flocons d''avoine dans de l''eau ou du lait, garnir de baies et de noix hachées.', 340, 10, 48, 14, 8, 12, 20, 'best_choice', 'High in fiber and unsaturated fat, with no added sugar needed.', 'Riche en fibres et en graisses insaturées, sans besoin de sucre ajouté.', array['high_fiber', 'unsaturated_fat']),
  ('Grilled Salmon with Brown Rice and Broccoli', 'Saumon grillé, riz brun et brocoli', 'Grilled salmon served with brown rice and steamed broccoli.', 'Saumon grillé servi avec du riz brun et du brocoli vapeur.', 'american', 'dinner', '1 plate', '1 assiette', jsonb_build_array(jsonb_build_object('en', 'Salmon', 'fr', 'Saumon'), jsonb_build_object('en', 'Brown rice', 'fr', 'Riz brun'), jsonb_build_object('en', 'Broccoli', 'fr', 'Brocoli'), jsonb_build_object('en', 'Olive oil', 'fr', 'Huile d''olive'), jsonb_build_object('en', 'Lemon', 'fr', 'Citron')), 'Grill the salmon with a little olive oil and lemon, serve with brown rice and steamed broccoli.', 'Griller le saumon avec un peu d''huile d''olive et de citron, servir avec du riz brun et du brocoli vapeur.', 480, 34, 45, 16, 6, 3, 180, 'best_choice', 'Lean protein, whole grains, and vegetables in one balanced plate.', 'Protéines maigres, céréales complètes et légumes dans une assiette équilibrée.', array['fish', 'whole_grain', 'high_fiber']),
  ('Chicken and Quinoa Bowl', 'Bol de poulet et quinoa', 'Grilled chicken over quinoa with mixed vegetables.', 'Poulet grillé sur lit de quinoa avec légumes mélangés.', 'american', 'lunch', '1 bowl', '1 bol', jsonb_build_array(jsonb_build_object('en', 'Chicken breast', 'fr', 'Blanc de poulet'), jsonb_build_object('en', 'Quinoa', 'fr', 'Quinoa'), jsonb_build_object('en', 'Bell peppers', 'fr', 'Poivrons'), jsonb_build_object('en', 'Spinach', 'fr', 'Épinards'), jsonb_build_object('en', 'Olive oil', 'fr', 'Huile d''olive')), 'Grill the chicken, combine with cooked quinoa and sautéed vegetables.', 'Griller le poulet, combiner avec le quinoa cuit et les légumes sautés.', 420, 36, 38, 12, 6, 4, 220, 'best_choice', 'A balanced combination of lean protein, whole grain, and vegetables.', 'Une combinaison équilibrée de protéines maigres, de céréales complètes et de légumes.', array['chicken', 'whole_grain', 'high_protein']),
  ('Turkey Whole-Grain Sandwich', 'Sandwich à la dinde sur pain complet', 'A simple turkey sandwich on whole-grain bread with vegetables.', 'Un sandwich simple à la dinde sur pain complet avec des légumes.', 'american', 'lunch', '1 sandwich', '1 sandwich', jsonb_build_array(jsonb_build_object('en', 'Turkey', 'fr', 'Dinde'), jsonb_build_object('en', 'Whole-wheat bread', 'fr', 'Pain complet'), jsonb_build_object('en', 'Lettuce', 'fr', 'Laitue'), jsonb_build_object('en', 'Tomato', 'fr', 'Tomate'), jsonb_build_object('en', 'Mustard', 'fr', 'Moutarde')), 'Layer turkey, lettuce, and tomato between two slices of whole-grain bread.', 'Empiler la dinde, la laitue et la tomate entre deux tranches de pain complet.', 320, 26, 34, 8, 5, 5, 620, 'good_choice', 'A practical lean-protein option — consider a lower-sodium deli turkey or bread when available.', 'Une option pratique de protéines maigres — envisagez une dinde ou un pain moins salés si possible.', array['turkey', 'whole_grain']),
  ('Lentil Soup', 'Soupe de lentilles', 'A hearty lentil soup with vegetables.', 'Une soupe de lentilles consistante avec des légumes.', 'american', 'lunch', '1 bowl', '1 bol', jsonb_build_array(jsonb_build_object('en', 'Lentils', 'fr', 'Lentilles'), jsonb_build_object('en', 'Carrots', 'fr', 'Carottes'), jsonb_build_object('en', 'Celery', 'fr', 'Céleri'), jsonb_build_object('en', 'Onion', 'fr', 'Oignon'), jsonb_build_object('en', 'Vegetable broth', 'fr', 'Bouillon de légumes')), 'Simmer lentils with chopped vegetables and low-sodium broth until tender.', 'Laisser mijoter les lentilles avec les légumes hachés et un bouillon faible en sodium jusqu''à tendreté.', 230, 14, 38, 1, 12, 5, 480, 'best_choice', 'High in fiber and plant protein — choose a low-sodium broth to keep sodium moderate.', 'Riche en fibres et en protéines végétales — choisissez un bouillon faible en sodium.', array['legume', 'high_fiber']),
  ('Bean and Vegetable Bowl', 'Bol de haricots et légumes', 'A simple bowl of beans and roasted vegetables.', 'Un bol simple de haricots et de légumes rôtis.', 'american', 'dinner', '1 bowl', '1 bol', jsonb_build_array(jsonb_build_object('en', 'Beans', 'fr', 'Haricots'), jsonb_build_object('en', 'Sweet potatoes', 'fr', 'Patates douces'), jsonb_build_object('en', 'Kale', 'fr', 'Chou frisé'), jsonb_build_object('en', 'Olive oil', 'fr', 'Huile d''olive')), 'Roast the sweet potato and kale, combine with warmed beans.', 'Rôtir la patate douce et le chou frisé, combiner avec les haricots réchauffés.', 360, 13, 55, 10, 14, 9, 140, 'best_choice', 'Plant-forward, high in fiber, and naturally low in sodium.', 'À dominante végétale, riche en fibres et naturellement faible en sodium.', array['legume', 'high_fiber']),
  ('Baked Sweet Potato with Salmon', 'Patate douce cuite au four avec saumon', 'A baked sweet potato served alongside grilled salmon.', 'Une patate douce cuite au four accompagnée de saumon grillé.', 'american', 'dinner', '1 plate', '1 assiette', jsonb_build_array(jsonb_build_object('en', 'Sweet potatoes', 'fr', 'Patates douces'), jsonb_build_object('en', 'Salmon', 'fr', 'Saumon'), jsonb_build_object('en', 'Green beans', 'fr', 'Haricots verts')), 'Bake the sweet potato, grill the salmon, and steam the green beans.', 'Cuire la patate douce au four, griller le saumon et cuire les haricots verts à la vapeur.', 410, 28, 40, 14, 7, 10, 110, 'best_choice', 'A balanced plate combining lean protein, fiber, and unsaturated fat.', 'Une assiette équilibrée combinant protéines maigres, fibres et graisses insaturées.', array['fish', 'high_fiber']),
  ('Greek Yogurt with Berries and Nuts', 'Yaourt grec aux baies et aux noix', 'Plain Greek yogurt topped with fresh berries and a small handful of nuts.', 'Yaourt grec nature garni de baies fraîches et d''une petite poignée de noix.', 'american', 'snack', '1 cup', '250 mL', jsonb_build_array(jsonb_build_object('en', 'Plain Greek yogurt', 'fr', 'Yaourt grec nature'), jsonb_build_object('en', 'Mixed berries', 'fr', 'Baies mélangées'), jsonb_build_object('en', 'Almonds', 'fr', 'Amandes')), 'Top plain Greek yogurt with berries and chopped almonds.', 'Garnir le yaourt grec nature de baies et d''amandes hachées.', 220, 18, 20, 8, 4, 14, 65, 'best_choice', 'High in protein with no added sugar when using plain yogurt.', 'Riche en protéines, sans sucre ajouté si le yaourt nature est utilisé.', array['high_protein', 'dairy']),
  ('Vegetable Omelet with Whole-Grain Toast', 'Omelette aux légumes et pain complet grillé', 'An omelet with mixed vegetables served with whole-grain toast.', 'Une omelette aux légumes mélangés servie avec du pain complet grillé.', 'american', 'breakfast', '1 plate', '1 assiette', jsonb_build_array(jsonb_build_object('en', 'Eggs', 'fr', 'Œufs'), jsonb_build_object('en', 'Spinach', 'fr', 'Épinards'), jsonb_build_object('en', 'Bell peppers', 'fr', 'Poivrons'), jsonb_build_object('en', 'Whole-wheat bread', 'fr', 'Pain complet')), 'Whisk eggs with chopped vegetables, cook in a lightly oiled pan, serve with toast.', 'Battre les œufs avec les légumes hachés, cuire dans une poêle légèrement huilée, servir avec le pain grillé.', 320, 20, 26, 15, 5, 4, 340, 'best_choice', 'A protein- and vegetable-forward breakfast with whole grains.', 'Un petit-déjeuner riche en protéines et en légumes, avec des céréales complètes.', array['eggs', 'whole_grain']),
  ('Chicken and Avocado Salad', 'Salade de poulet et avocat', 'Grilled chicken and avocado over mixed greens.', 'Poulet grillé et avocat sur un mélange de jeunes pousses.', 'american', 'lunch', '1 bowl', '1 bol', jsonb_build_array(jsonb_build_object('en', 'Chicken breast', 'fr', 'Blanc de poulet'), jsonb_build_object('en', 'Avocado', 'fr', 'Avocat'), jsonb_build_object('en', 'Mixed greens', 'fr', 'Jeunes pousses mélangées'), jsonb_build_object('en', 'Tomatoes', 'fr', 'Tomates'), jsonb_build_object('en', 'Olive oil and lemon dressing', 'fr', 'Vinaigrette huile d''olive et citron')), 'Toss grilled chicken, sliced avocado, and vegetables with a light olive oil and lemon dressing.', 'Mélanger le poulet grillé, l''avocat tranché et les légumes avec une vinaigrette légère à l''huile d''olive et au citron.', 390, 32, 14, 24, 8, 4, 190, 'best_choice', 'Lean protein with fiber and unsaturated fat from avocado and olive oil.', 'Protéines maigres avec des fibres et des graisses insaturées provenant de l''avocat et de l''huile d''olive.', array['chicken', 'high_fiber', 'unsaturated_fat'])
) as v(name_en, name_fr, description_en, description_fr, cuisine, meal_type, serving_size_en, serving_size_fr, ingredients, preparation_en, preparation_fr, calories_kcal, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, rating, rating_reason_en, rating_reason_fr, tags)
